mapper.update:
UPDATE turn
SET status        = #{toStatus},
    finished_at   = #{finishedAt},
    silent_reason = #{silentReason},
    error_code    = #{errorCode}
WHERE id = #{id}
  AND status = #{fromStatus}

UPDATE turn
SET outbox_ids = #{outboxIds}
WHERE id = #{id}

UPDATE turn
SET trigger_ids = #{triggerIds}
WHERE id = #{id}

mapper.select:
SELECT TIMESTAMPDIFF(MICROSECOND, accepted_at, finished_at) DIV 1000
FROM turn
WHERE finished_at IS NOT NULL
AND accepted_at >= #{from}
AND accepted_at <= #{to}
AND group_id = #{groupId}

SELECT status, COUNT(*) AS count
FROM turn
WHERE 1 = 1
AND accepted_at >= #{from}
AND accepted_at <= #{to}
AND group_id = #{groupId}
GROUP BY status

SELECT COUNT(*)
FROM turn
WHERE status = 'FAILED'
AND error_code LIKE CONCAT(#{errorCodePrefix}, '%')
AND accepted_at >= #{from}
AND accepted_at <= #{to}
